#include "MilitaryReadinessRuntime.hpp"
namespace elysium::fortress {bool MilitaryReadinessRuntime::upsert(Squad s){if(!s.id)return false;squads_[s.id]=std::move(s);return true;}ReadinessSummary MilitaryReadinessRuntime::readiness(StableId id)const{ReadinessSummary r;auto i=squads_.find(id);if(i==squads_.end()){r.blockers={"unknown squad"};return r;}if(i->second.members.empty()){r.blockers={"no members"};return r;}for(auto&m:i->second.members){double x=std::clamp(m.health,0.0,1.0)*std::clamp(m.training,0.0,1.0)*std::clamp(m.equipment,0.0,1.0)*std::clamp(m.ammo,0.0,1.0)*std::clamp(m.access,0.0,1.0);r.score+=x;if(m.equipment<.5)r.blockers.push_back("missing gear");if(m.ammo<.5)r.blockers.push_back("low ammo");if(m.access<.5)r.blockers.push_back("blocked route");}r.score/=i->second.members.size();return r;}}
